DEFINITIONS=[{'symbol': '002822', 'primary': '1225381688', 'pages': [1], 'risk_group': '主要账户解冻，但撤销申请尚未全部获批', 'known_at_anchor': '6月23日披露主要银行账户解冻、正常收付功能恢复，已申请撤销剩余其他风险警示。4月提交的另外两项撤销申请仍在补材料；截至本件各项均已提出申请，不等于已经摘帽。', 'watch': '核交易所正式同意及生效日、新经营与现金；旧重整执行和审计影响消除不替代撤销批准，也不外推后来盈利。', 'supporting': [{'id': '1225155507', 'pages': [2, 3], 'note': '会计师确认2025标准无保留、旧持续经营保留事项影响消除；签章页为扫描空提取，视觉确认4月21日，原空文本保留。'}]}, {'symbol': '002856', 'primary': '1225248771', 'pages': [2], 'risk_group': '负净资产与持续经营不确定性双重约束', 'known_at_anchor': '4月30日起退市风险警示及其他ST：2025归母净资产为负5246.62万元，连续三年扣非前后孰低利润为负并有持续经营重大不确定性。财报为无保留附持续经营段，不写成保留意见。', 'watch': '核净资产、真实盈利和现金修复、新审计及正式撤销；有效内控意见不等于持续经营无风险，董事会改善计划也不当已实现。', 'supporting': [{'id': '1225248784', 'pages': [2], 'note': '会计师直接确认无保留附持续经营重大不确定性；净亏损及流动负债高于流动资产是不同口径。'}, {'id': '1225248801', 'pages': [3, 4], 'note': '2025年末财报内控审计认为所有重大方面有效；签章页空提取以已核视觉证明日期，不填入原提取。'}]}, {'symbol': '002872', 'primary': '1225366268', 'pages': [1, 3], 'risk_group': '占用一项已撤销，处罚相关警示仍保留', 'known_at_anchor': '6月12日公告确认占用资金触发的其他ST已获交易所批准撤销；不是这项仍在等批准。但2017—2018年报虚假记载相关处罚触发的其他ST继续保留，简称与涨跌幅不因本次部分撤销改变。', 'watch': '分别核剩余处罚警示条件、正式撤销和新经营。6月公告称处罚决定未满12个月、条件未全满足；以后满日历年不自动等于摘帽。', 'supporting': [{'id': '1225249854', 'pages': [2], 'note': '占用本金125074926元于2020年6月2日前已收，利息15512720.35元于2021年4月8日前已收；2026专项说明不是2026新增现金。'}]}, {'symbol': '002883', 'primary': '1225266057', 'pages': [1], 'risk_group': '扣除后营收不足3亿元且亏损，另有历史报表更正', 'known_at_anchor': '5月6日起退市风险警示。2025总营收约3.70亿元，但扣除后约2.51亿元，利润总额、归母与扣非利润均负，触及组合财务条件；不能用未扣除营收代替规则口径。', 'watch': '核扣除口径、当期经营、新审计及正式撤销；前期差错导致2023由盈转亏，与2025财务警示分开，不混同年度或将重新审计当风险解除。', 'supporting': [{'id': '1225266086', 'pages': [1], 'note': '更正2022年至2025年前三季报表，2023归母由盈利转亏，4月公告要求另出更正后2023审计报告。'}, {'id': '1225395270', 'pages': [2], 'note': '6月30日已披露更正后2023审计报告，4月“等待重新审计”状态已有后续文件；不等于2025警示消除。'}]}]
